INSERT INTO industry_metric(theme_id, metric_code, as_of_date, published_at, value, unit, source_document_id)
SELECT id, #{metricCode}, #{asOfDate}, #{publishedAt}, #{value}, #{unit}, #{sourceId}
FROM theme
WHERE code=#{themeCode}

